import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { useSheetToday } from '../sheet/sheet';
import { peopleKey } from './people';
import type { Person } from './people';

/** Whether the person is retired and from when, and the form that retires them from a date (blank: the
 *  sheet's today). A claim dated after it is then refused; their claims keep counting in every total. */
function PersonRetire({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const today = useSheetToday(sheetId);
  const [from, setFrom] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const retire = useMutation({
    mutationFn: (body: { user: string; from: string }) =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/retire`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      setFrom('');
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not retire ${person.name}: the date must be yyyy-mm-dd.`),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!once.start()) return;
    retire.mutate({ user, from: from.trim() });
  };

  return (
    <td>
      Retired <span data-testid="person-retired">{person.retiredFrom !== null ? 'yes' : 'no'}</span>{' '}
      from <span data-testid="person-retired-from">{person.retiredFrom ?? ''}</span>{' '}
      <form onSubmit={submit} style={{ display: 'inline' }}>
        <input
          data-testid="person-retire-date"
          placeholder={today || 'yyyy-mm-dd'}
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            setError('');
          }}
        />{' '}
        <button type="submit" data-testid="person-retire" disabled={retire.isPending}>
          Retire
        </button>
      </form>
      {error && (
        <p data-testid="person-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 40, Component: PersonRetire });

/** The period whose dates contain the date (yyyy-mm-dd), or undefined when none does. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** A period's due-total as shown on its row: the one fixed when it was closed, else the dues (as shown on their
 *  rows) of the claims among these that count (see live) whose date falls in it. */
export function periodDueTotal(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: string,
    late: Late): string {
  if (period.closedTotal !== null) return period.closedTotal;
  const byId = new Map(people.map((p) => [p.id, p]));
  return sumDue(
    live(claims, people)
      .filter((c) => periodOf([period], c.date))
      .map((c) => claimDue(c, rateOn(rates, gradeOn(byId.get(c.personId), c.date), c.date), floor, late)),
  );
}
import { PersonRow } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheet';
import { gradeOn, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { claimDue, rateOn, sumDue, useRates } from '../rates/rates';
import type { Late, Rate } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { live, overdue, useClaims } from './claims';
import type { Claim } from './claims';

/** The overdue claims that count among these, with the due of each (as shown on its row). */
function overdueDues(claims: Claim[], people: Person[], rates: Rate[], late: Late, floor: string) {
  const byId = new Map(people.map((p) => [p.id, p]));
  return live(claims, people)
    .filter((c) => overdue(c, late.today))
    .map((c) => claimDue(c, rateOn(rates, gradeOn(byId.get(c.personId), c.date), c.date), floor, late));
}

function useOverdue(sheetId: string, people: Person[], claims: Claim[]) {
  const rates = useRates(sheetId).data ?? [];
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const dues = overdueDues(claims, people, rates, late, floor);
  return { count: dues.length, total: sumDue(dues) };
}

